INSERT INTO feature VALUES('product-eta','conversion','Eta for products, records and pairs','normalization-by-evaluation','implemented','notable',NULL,'A tuple, a record or a dependent pair converts with a neutral of its type by the neutral''s projections, in the engine and the kernel alike. The unit, the tuple and the record of no components, converts with every neutral of its type. Two neutrals of the unit type stay apart unless they are one term, because conversion reads no type (#6161).','core-nbe kernel-core','corpus/model/data/eta.gandr corpus/pathological/data/eta.gandr','corpus/model/data/eta.gandr',NULL);
